// Combine layouts + theme + images → visual_specs
const images = $input.first().json;
let theme = 'tokyo-night';
try {
  theme = $('Use User Theme').first().json.selected_theme;
} catch (e) {
  try {
    let llmOut = $('LLM: Select Theme').first().json.output || '{}';
    llmOut = llmOut.replace(/<think>[\s\S]*?<\/think>/g, "").trim();
    const parsed = JSON.parse(llmOut.replace(/```json\n?|```/g, ""));
    theme = parsed.theme || 'tokyo-night';
  } catch (e2) {
    theme = 'tokyo-night';
  }
}

return [{
  json: {
    job_id: $('Start').first().json.job_id,
    slides: $('Start').first().json.slides,
    output_format: $('Start').first().json.output_format,
    visual_specs: {
      theme: theme,
      layouts: $('Parse Layouts').first().json.layouts,
      images: images.image_paths || {}
    }
  }
}];
